using Invoicing.Legacy;

namespace Invoicing;

/// <summary>Exports an invoice as a PDF byte stream.</summary>
public sealed class PdfExporter
{
    private readonly IInvoiceRenderer _renderer;

    public PdfExporter(IInvoiceRenderer renderer)
    {
        _renderer = renderer ?? throw new ArgumentNullException(nameof(renderer));
    }

    public byte[] Export(Invoice invoice)
    {
        ArgumentNullException.ThrowIfNull(invoice);
        var lines = invoice.Lines
            .Select(line => $"{line.Description}: {line.NetAmount}")
            .ToArray();

        return _renderer.Render($"Invoice {invoice.Number}", lines);
    }
}

public interface IInvoiceRenderer
{
    byte[] Render(string title, IReadOnlyCollection<string> lines);
}

public sealed class SupportedInvoiceRenderer : IInvoiceRenderer
{
    public byte[] Render(string title, IReadOnlyCollection<string> lines)
        => RenderApiV2.ToPdf(title, lines);
}
